function Inquiry({kind,reference=''}:{kind:string;reference?:string}){
 const [state,setState]=useState('');const [busy,setBusy]=useState(false);const car=kind==='vender-coche';const rental=kind.startsWith('alquiler')
 async function send(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;setBusy(true);setState('');try{const r=await fetch('/api/inquiries',{method:'POST',body:new FormData(form)});const result=await r.json();if(!r.ok)throw Error(result.error);setState('Solicitud recibida. Queda privada y pendiente de revisión.');form.reset()}catch(err){setState(err instanceof Error?err.message:'No se ha enviado la solicitud.')}finally{setBusy(false)}}
 return <section id={kind==='alquiler-villas'?'consulta-villas':undefined} className={`inquiry inquiry-${kind}`}><div><span className="eyebrow">ATENCIÓN PERSONALIZADA</span><h2>{car?'Cuéntanos sobre tu coche.':kind==='coches-en-venta'?'Cuéntanos qué coche buscas.':kind==='villas-en-venta'?'Busquemos tu próxima propiedad.':kind==='alquiler-villas'?'Diseñemos tu próxima estancia.':kind==='ocio-vip'?'Planifiquemos tu próxima experiencia.':kind==='cursos-mentorias'?'Encuentra la formación adecuada.':kind==='relojes-diamantes-joyas'?'Consulta nuestra selección privada.':'Cuéntanos qué necesitas.'}</h2><p>Tus datos se utilizan únicamente para gestionar esta consulta. No se publica ningún anuncio automáticamente.</p><a className="textlink" href={WA}>También por WhatsApp <ArrowUpRight size={16}/></a></div><form onSubmit={send}><input type="hidden" name="kind" value={kind}/><input type="hidden" name="reference" value={reference}/><label className="honeypot">No completar<input name="website" tabIndex={-1} autoComplete="off"/></label><div className="formgrid"><label>Nombre<input name="name" required maxLength={150} autoComplete="name"/></label><label>Correo electrónico<input name="email" type="email" required autoComplete="email"/></label><label>Teléfono<input name="phone" type="tel" required={car} autoComplete="tel"/></label>{car?<><label>Marca<input name="brand" required/></label><label>Modelo<input name="model" required/></label><label>Año<input name="year" type="number" min="1900" max={new Date().getFullYear()+1} required/></label><label>Kilometraje<input name="mileage" type="number" min="0" required/></label><label>Precio solicitado (€)<input name="price" type="number" min="0" required/></label></>:null}{rental?<><label>Fecha de entrada / recogida<input name="checkin" type="date" required min={new Date().toISOString().slice(0,10)}/></label><label>Fecha de salida / devolución<input name="checkout" type="date" required/></label>{kind==='alquiler-villas'&&<label>Huéspedes<input name="guests" type="number" min="1" required/></label>}<label>Presupuesto (€)<input name="budget" type="number" min="0"/></label></>:null}</div><label> {car?'Descripción y estado del vehículo':'¿Qué tienes en mente?'}<textarea name="description" rows={4} required maxLength={8000}/></label>{car&&<label>Fotografías del vehículo <small>Hasta 6 JPG, PNG o WebP. Máximo 4,5 MB en total.</small><input type="file" name="photos" multiple accept="image/jpeg,image/png,image/webp"/></label>}<label className="consent"><input type="checkbox" name="consent" required/><span>He leído la <a href="/privacidad">política de privacidad</a> y acepto el tratamiento de mis datos para esta consulta.</span></label><button className="button gold" disabled={busy}>{busy?'Enviando…':'Enviar solicitud privada'} <ArrowUpRight size={16}/></button><p role="status" className="form-status">{state}</p>{rental&&<small>La solicitud no confirma una reserva. La disponibilidad debe verificarse personalmente.</small>}</form></section>
}
